// Contrato de entrada — lo define NUESTRO workflow WF-01 de GHL, no GHL: el paso
// "Webhook" de un GHL Workflow deja mapear campos a mano. Está documentado en la guía
// de provisión; si cambia allá, cambia acá.
//   { contactId, conversationId, messageId, body, attachments[], phone, canal }
const j0 = $input.first().json || {};
const src = (j0.body && j0.body.contactId !== undefined) ? j0.body : j0;

if (!src.contactId) {
  throw new Error('W1: el relay no mandó contactId. ' +
    'Revisar el mapeo del paso Webhook en WF-01.');
}

let adj = src.attachments ?? [];
if (typeof adj === 'string') {
  const t = adj.trim();
  adj = t.startsWith('[') ? JSON.parse(t) : (t ? [t] : []);
}
if (!Array.isArray(adj)) adj = adj ? [adj] : [];

const texto = String(src.body ?? '').trim();

// Ruteo por tipo, réplica de `checkType` del origen (text / voice / Image).
let tipo = 'texto';
const url0 = String(adj[0] || '').toLowerCase();
if (adj.length) {
  if (/\.(ogg|oga|mp3|m4a|wav|amr)(\?|$)/.test(url0)) tipo = 'audio';
  else if (/\.pdf(\?|$)/.test(url0)) tipo = 'pdf';
  else tipo = 'imagen';
}

// El messageId es la clave de idempotencia, y hace falta porque el debounce hace
// timeoutear el webhook de GHL: si GHL reintenta, el mismo mensaje entra dos veces.
//
// Pero no está garantizado que el relay mande uno: depende de si el trigger de GHL
// expone un id por mensaje, y el paso "Webhook" de un GHL Workflow mapea campos a
// mano. Si no viene, se deriva del contenido — determinístico, así que el reintento
// del MISMO mensaje cae en la misma clave.
//
// No se usa crypto: el sandbox del nodo Code no garantiza los builtins de Node. El
// hash es FNV-1a de 32 bits, que para desambiguar mensajes de un mismo contacto
// dentro de una ventana de 3 minutos sobra.
function huella(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

let messageId = src.messageId ? String(src.messageId).trim() : '';
const derivado = !messageId;
if (derivado) {
  // El id lleva el contactId adelante para que sea legible en la tabla y en los logs,
  // y para que dos leads que escriben lo mismo nunca colisionen.
  messageId = 'auto:' + String(src.contactId) + ':' +
              huella([texto, adj.join('|')].join('\u0001'));
}

return [{ json: {
  contactId: String(src.contactId),
  conversationId: src.conversationId ? String(src.conversationId) : null,
  messageId,
  messageId_derivado: derivado,
  phone: src.phone ? String(src.phone) : null,
  canal: src.canal || 'WhatsApp',
  texto,
  adjuntos: adj,
  tipo,
  // el test manda debounce_seg: 0; producción usa los del origen (50 texto / 15 imagen)
  debounce_seg: src.debounce_seg !== undefined
    ? Number(src.debounce_seg)
    : (tipo === 'imagen' ? 15 : 50),
  recibido_at: $now.toISO(),
  // seam de test, ver la guardia de horario de W7
  _forzar_fuera_horario: src._forzar_fuera_horario === true,
} }];

