CREATE TABLE IF NOT EXISTS hpf_mensajes_vistos (
  message_id text PRIMARY KEY,
  visto_at   timestamptz NOT NULL DEFAULT now()
);
DELETE FROM hpf_mensajes_vistos WHERE visto_at < now() - interval '24 hours';
INSERT INTO hpf_mensajes_vistos (message_id) VALUES ($1)
ON CONFLICT (message_id) DO UPDATE
  SET visto_at = now()
  WHERE $2::boolean
    AND hpf_mensajes_vistos.visto_at < now() - interval '3 minutes'
RETURNING message_id;

