// Traducción de los gates de etapa del origen. En Kommo se hacía con `contains` sobre
// el JSON del lead serializado — de ahí el bug del "143" que matcheaba cualquier
// timestamp. Acá es igualdad de UUID.
const ETAPAS = {
  "Lead Nuevo": "cf8fc770-81b1-422c-8394-d00bfb97a3f0",
  "Saludo Enviado": "f9709293-d03c-47f1-949f-0c03ab077a45",
  "Evento Identificado": "fec50c94-fba0-444b-8c75-7a97da9e0daa",
  "Productos Mostrados": "49c7401f-8af1-4d8f-a1b4-e989b6d0a5e2",
  "Cotizado": "96fa0ade-c853-4db3-97f4-56d58d69af8c",
  "Esperando Pago": "843a06f1-1214-4baa-a3a0-f197cb240b5d",
  "Pago Confirmado": "96d760e5-f290-456c-a117-57e61ce6c27d",
  "Diseño en Proceso": "d35bb30d-97d5-48c4-81f8-5ecabf32e57d",
  "En Producción": "008689c6-80d8-4712-981b-1d800e1e6137",
  "Enviado": "218b9b41-4007-4b1c-bbe4-4e775ddf00b5",
  "En Espera": "48de80e9-31a9-472a-b030-5b9fe9174810",
  "Ganado": "909a816d-997e-4d90-8dc1-dc4b0dcd16d7",
  "Ventas Perdidas": "6abfe419-adf2-4df5-87c5-ef4f62e01464"
};
const nombreDe = Object.fromEntries(Object.entries(ETAPAS).map(([k, v]) => [v, k]));

// El agente se calla en estas etapas (equivale a If7/If9/If12/If20 + "Si está en perdidos")
const BLOQUEO = {
  'En Espera':        'atencion_humana',   // Kommo 91266100 atención personalizada
  'Pago Confirmado':  'pago_confirmado',   // Kommo 91450360
  'En Producción':    'en_produccion',     // Kommo 100395519
  'Ventas Perdidas':  'perdido',           // Kommo 143
  'Ganado':           'ganado',            // Kommo 142
};

const ctx  = $('Normalizar entrada').first().json;
const ses  = $('Resolver identidad').first().json;
const opp  = ($input.first().json.data || {}).opportunity || {};
const via  = $('W0 · find or create').first().json.via || null;
const hist = $('¿Hay historial?').first().json || {};
const turnosPrevios = Number(hist.turnos_previos || 0);

const etapaId     = opp.pipelineStageId || null;
const etapaNombre = nombreDe[etapaId] || null;
const motivo      = BLOQUEO[etapaNombre] || null;

// Cliente que vuelve: la oportunidad ya existía y está cerrada. En Kommo esto era un
// lead nuevo; acá hay que reciclar la misma (ver PM-IDN-03-decision.md).
const vuelve = via === 'existente' && ['Ganado', 'Ventas Perdidas'].includes(etapaNombre);

let ruta = 'seguir';
if (vuelve) ruta = 'cliente_vuelve';
else if (motivo) ruta = 'bloqueado';

return [{ json: {
  ...ctx,
  sessionId: ses.session_id,
  opportunityId: opp.id || null,
  etapa_id: etapaId,
  etapa: etapaNombre,
  via_oportunidad: via,
  ruta,
  motivo_bloqueo: motivo,
  // Sale de la memoria, no del CRM — ver SQL_HISTORIAL.
  primer_contacto: turnosPrevios === 0,
  turnos_previos: turnosPrevios,
  gates: { etapa: etapaNombre, bloqueo: motivo, via, cliente_vuelve: vuelve,
           primer_contacto: turnosPrevios === 0 },
} }];

// Debounce "gana el último", igual que el origen: cada mensaje empuja a una lista de
// Redis y duerme; al despertar sólo sigue la ejecución cuyo texto sigue siendo el
// último de la lista. Las demás mueren acá.
//
// Ojo: el origen tenía este mismo mecanismo ROTO en la rama de imagen — `Guardar1`
// empujaba `$workflow.id`, que es constante, así que la comparación daba siempre true
// y no deduplicaba nada. Acá se empuja el messageId, que sí es único.
const ctx  = $('Evaluar estado').first().json;
const raw  = $input.first().json;
const lista = raw.Mensajes ?? raw.propertyName ?? raw ?? [];
const arr = Array.isArray(lista) ? lista : [lista];
const ultimo = arr.length ? String(arr[arr.length - 1]) : null;
const soyElUltimo = ultimo === ctx.messageId;

return [{ json: {
  ...ctx,
  debounce: { acumulados: arr.length, ultimo, soy_el_ultimo: soyElUltimo,
              mensajes: arr },
  soy_el_ultimo: soyElUltimo,
} }];

// Una nota de voz es un mensaje de texto más. En el origen `transcribe voice` vuelve
// a `Get_Text`, o sea que el audio se reinyecta en el carril común y sigue el mismo
// camino que cualquier mensaje escrito — Router incluido. Se replica eso.
const ctx = $('¿Soy el último?').first().json;
const t = $input.first().json || {};
const texto = String(t.text ?? t.transcription ?? t.content ?? '').trim();
if (!texto) {
  throw new Error('W1: la transcripción del audio vino vacía');
}
return [{ json: { ...ctx, texto, tipo: 'texto', tipo_original: 'audio' } }];

// Convergencia de los dos cerebros. Se lee por nombre de nodo y no por $json porque
// sólo uno de los dos corrió; el otro ni existe en este runData.
const w7 = $('W7 · media');
if (w7.isExecuted) return [{ json: w7.first().json }];
const w6 = $('W6 · conversación');
if (w6.isExecuted) return [{ json: w6.first().json }];
throw new Error('W1: ni W6 ni W7 produjeron respuesta');

const ctx = $('Evaluar estado').first().json;
const cerebro = $('Resultado del cerebro').first().json;
const destino = cerebro.etapa_destino || null;

// Escalera del embudo. Fuera de ella (En Espera, Pago Confirmado, En Producción,
// Ganado, Ventas Perdidas, …) NO se toca nada: son estados que maneja una persona
// o la rama de pago, y pisarlos con un avance automático sería destructivo.
// 'Esperando Pago' y 'Pago Confirmado' entran en la escalera porque el carril de
// media las produce: un comprobante válido avanza a 'Pago Confirmado'. Sin ellas el
// guard monótono rechazaba ese avance por no encontrar el destino en la lista.
const ESCALERA = ['Lead Nuevo', 'Saludo Enviado', 'Evento Identificado',
                  'Productos Mostrados', 'Cotizado', 'Esperando Pago',
                  'Pago Confirmado'];
const actual = ESCALERA.indexOf(ctx.etapa);
const nuevo  = ESCALERA.indexOf(destino);

// DELTA declarado: el origen NO es monótono (sus If21/If8 dejan volver a ETAPA 2 a
// un lead que ya estaba en ETAPA 4). Acá sólo se avanza. Retroceder la etapa borra
// el trabajo comercial que ya se hizo sobre ese lead.
const avanza = destino !== null && actual >= 0 && nuevo > actual;

return [{ json: { ...ctx, etapa_destino: destino, etapa_actual: ctx.etapa,
                  avanza_etapa: avanza } }];

// Objeto de evidencia del turno completo. Es lo que el runner de paridad lee del
// runData: qué entró, por dónde ruteó, qué tools usó y qué salió a GHL.
//
// El envío se toma por nombre de nodo y NO de $json: desde que la escritura de
// etapa se metió en el medio, `$input` acá es la salida de `¿Avanza la etapa?` o
// la de `W0 · avanzar etapa`, no la de W2. Es la trampa que documenta
// _core/standards/n8n-data-references.md.
const ctx = $('Evaluar estado').first().json;
const cerebro = $('Resultado del cerebro').first().json;
// Cuando el cerebro no devuelve nada que mandar (imagen de un lead en producción, que
// el origen también contesta con silencio) W2 no corre.
const w2 = $('W2 · enviar');
const envio = w2.isExecuted ? w2.first().json : { partes_enviadas: 0, enviados: [] };
const etapas = $('Decidir etapa').first().json;
return [{ json: {
  ok: true,
  sessionId: ctx.sessionId, contactId: ctx.contactId, opportunityId: ctx.opportunityId,
  entrada: { texto: ctx.texto, tipo: ctx.tipo, adjuntos: ctx.adjuntos },
  etapa: ctx.etapa, gates: ctx.gates,
  primer_contacto: ctx.primer_contacto, turnos_previos: ctx.turnos_previos,
  messageId: ctx.messageId, messageId_derivado: ctx.messageId_derivado,
  etapa_destino: etapas.etapa_destino, etapa_avanzada: etapas.avanza_etapa,
  step: cerebro.step,
  tools_usadas: cerebro.tools_usadas || [],
  partes_enviadas: envio.partes_enviadas ?? null,
  enviados: envio.enviados || [],
} }];

// Qué campaña de re-enganche arma este turno. Réplica de qué sub-workflow disparaba
// cada agente en el origen:
//   Starter (step_1)    → seg-rebeca
//   Main Image (step_2) → seg-imagen
//   Products (step_3)   → seg-cotizacion
//   Recolector que COTIZÓ → seg-7pasos
// Un step_4 que no cotiza no arma nada, y de paso mata la campaña anterior.
//
// DELTA declarado: en el origen, un step_3 que además cotizaba disparaba LAS DOS
// cadenas. Acá gana 7pasos, porque la tabla tiene una fila por sesión.
const ctx = $('Evaluar estado').first().json;
const cerebro = $('Resultado del cerebro').first().json;
const step = cerebro.step;

let campania = null;
if (cerebro.etapa_destino === 'Cotizado') campania = '7pasos';
else if (step === 'step_1') campania = 'rebeca';
else if (step === 'step_2') campania = 'imagen';
else if (step === 'step_3') campania = 'cotizacion';

const ahora = Date.now();
// La primera ola va a la hora; 7pasos no manda olas, sólo evalúa a las 24 h.
const proximo = (campania && campania !== '7pasos')
  ? new Date(ahora + 60 * 60000).toISOString() : null;
const evalAt = (campania === '7pasos')
  ? new Date(ahora + 24 * 3600000).toISOString() : null;

return [{ json: {
  session_id: ctx.sessionId,
  contact_id: ctx.contactId,
  opportunity_id: ctx.opportunityId,
  campania,
  etapa_al_armar: cerebro.etapa_destino || ctx.etapa,
  evento: cerebro.evento || null,
  proximo_at: proximo,
  evaluacion_at: evalAt,
  evaluacion_desde_at: evalAt ? new Date(ahora).toISOString() : null,
} }];

// Telegram → el payload que espera W1, que es el de GHL.
//
// W1 exige `contactId` de GHL y un usuario de Telegram no tiene teléfono, así que se le
// fabrica uno con el prefijo +999 (código de país SIN ASIGNAR: no puede pisar el número
// de un lead real). El nodo siguiente hace upsert_contact con ese teléfono y devuelve un
// contactId de verdad, así el resto del pipeline no se entera de que vino de Telegram.
//
// El mismo prefijo es lo que W2 mira después para decidir si responde por Telegram o por
// GHL — por eso no se puede cambiar acá sin cambiarlo allá.
const j = $input.first().json || {};
const msg = j.message || j;
const chat = msg.chat || {};
const from = msg.from || {};
const chatId = String(chat.id ?? from.id ?? '');
if (!chatId) throw new Error('W1/TG: mensaje de Telegram sin chat id');

const nombre = [from.first_name, from.last_name].filter(Boolean).join(' ')
             || from.username || ('Telegram ' + chatId);

const texto = String(msg.text || msg.caption || '').trim();

// ── adjuntos ──────────────────────────────────────────────────────────────────────────
// Telegram entrega los adjuntos como `file_id`. Acá SÓLO se decide cuál se canjea y con
// qué extensión va a quedar; el canje lo hacen `TG · bajar archivo` → `TG · subir a GHL`.
//
// La extensión NO se lee de Telegram. `file_path` de la Bot API suele traerla bien, pero
// es un dato que no controlamos y de él depende TODA la clasificación que hace
// `Normalizar entrada`, que mira exclusivamente la extensión de adjuntos[0]:
//     .ogg .oga .mp3 .m4a .wav .amr → audio   (→ Whisper)
//     .pdf                          → pdf     (→ W7, sin visión)
//     cualquier otro adjunto        → imagen  (→ W7, visión de OpenAI)
// Un video queda como 'imagen' y la visión lo rechaza: es EXACTAMENTE lo que le pasa hoy
// a un lead real que manda un video por WhatsApp. Se replica a propósito — esta Fase 0
// existe para que la guía de paridad DESCUBRA estas cosas, no para taparlas.
const MAX = 20 * 1024 * 1024;   // techo duro de getFile en la Bot API

// Extensiones que un `document` puede tener para que valga la pena subirlo. Es más
// estricto que producción, y sólo acá: sin esto un .zip se sube, la visión lo rechaza y
// el caso de prueba "documento no soportado" no tiene resultado observable.
const DOC_OK = ['pdf', 'jpg', 'jpeg', 'png', 'webp', 'gif',
                'ogg', 'oga', 'mp3', 'm4a', 'wav', 'amr', 'mp4', 'mov', 'm4v'];

const extDe = (n, def) => {
  const m = String(n || '').toLowerCase().match(/\.([a-z0-9]{1,5})$/);
  return m ? m[1] : def;
};

let media = null;     // { file_id, ext, clase, bytes }
let rechazo = '';

if (Array.isArray(msg.photo) && msg.photo.length) {
  // `photo` es el array de tamaños, ordenado de menor a mayor. El último es el que le
  // sirve a la visión.
  const p = msg.photo[msg.photo.length - 1];
  media = { file_id: p.file_id, ext: 'jpg', clase: 'foto',
            bytes: Number(p.file_size || 0) };
} else if (msg.voice) {
  // Las notas de voz de Telegram son OGG/Opus. Va como '.ogg' y NO '.oga': la Media Library
  // de GHL valida por EXTENSIÓN, no por contenido, y rechaza .oga con
  // 400 INVALID_FILE_TYPE. Medido el 2026-08-20 subiendo el MISMO archivo dos veces,
  // byte por byte idéntico, cambiando sólo el nombre: .oga → 400, .ogg → 201.
  // (También aceptan .mp3 y .wav; .m4a también da 400.)
  // Con .oga el audio moría en el upload y NUNCA llegaba a Whisper.
  // El regex de audio de `Normalizar entrada` matchea .ogg igual, así que no cambia nada aguas abajo.
  media = { file_id: msg.voice.file_id, ext: 'ogg', clase: 'nota de voz',
            bytes: Number(msg.voice.file_size || 0) };
} else if (msg.audio) {
  media = { file_id: msg.audio.file_id, ext: extDe(msg.audio.file_name, 'mp3'),
            clase: 'audio', bytes: Number(msg.audio.file_size || 0) };
} else if (msg.video_note) {
  media = { file_id: msg.video_note.file_id, ext: 'mp4', clase: 'video',
            bytes: Number(msg.video_note.file_size || 0) };
} else if (msg.animation) {
  // Un GIF de Telegram es un mp4, y viene con `animation` Y `document` poblados a la vez.
  // Por eso va ANTES de document: si no, entra por la rama equivocada.
  media = { file_id: msg.animation.file_id, ext: 'mp4', clase: 'video',
            bytes: Number(msg.animation.file_size || 0) };
} else if (msg.video) {
  media = { file_id: msg.video.file_id, ext: extDe(msg.video.file_name, 'mp4'),
            clase: 'video', bytes: Number(msg.video.file_size || 0) };
} else if (msg.document) {
  const ext = extDe(msg.document.file_name, '');
  if (DOC_OK.includes(ext)) {
    media = { file_id: msg.document.file_id, ext, clase: 'documento',
              bytes: Number(msg.document.file_size || 0) };
  } else {
    // El nombre del archivo NO se echa en el aviso: un 'mi_archivo.zip' metería un '_'
    // suelto y, si el nodo de Telegram sale con parse_mode, eso es un 400.
    rechazo = 'No puedo procesar ese tipo de archivo. Mandame una foto, un PDF o una nota de voz.';
  }
} else if (msg.sticker) {
  rechazo = 'No puedo procesar stickers. Mandame una foto, un PDF o una nota de voz.';
} else if (msg.location || msg.venue) {
  rechazo = 'No puedo procesar ubicaciones. Escribime la direccion como texto.';
} else if (msg.contact || msg.poll || msg.dice || msg.game) {
  rechazo = 'No puedo procesar ese tipo de mensaje. Mandame texto, una foto, un PDF o una nota de voz.';
}

// getFile devuelve 400 arriba de 20 MB y no hay manera de bajar el archivo. Se corta acá,
// con el file_size que ya viene en el update, para dar un mensaje entendible en vez del
// error crudo de la API.
if (media && media.bytes > MAX) {
  rechazo = 'Ese archivo pesa mas de 20 MB y Telegram no me deja bajarlo. Mandame uno mas chico.';
  media = null;
}

// Sin texto y sin adjunto reconocible no hay nada que procesar. Ojo: una FOTO SIN CAPTION
// no cae acá — tiene media, y el mensaje de imagen con texto vacío es válido de punta a
// punta (W7 hace String(src.texto ?? '') y la visión sólo usa la URL).
if (!media && !rechazo && !texto) {
  rechazo = 'No pude leer ese mensaje. Mandame texto, una foto, un PDF o una nota de voz.';
}

return [{ json: {
  _tg_chat_id: chatId,
  _tg_nombre: nombre,
  // Se sigue emitiendo porque es diagnóstico útil en el log, pero YA NO ES UN GUARD: si
  // alguien lo cablea "para completar", rompe las fotos sin caption. El guard real es
  // `_tg_ruta`.
  _tg_sin_texto: !texto,
  telefono_sintetico: '+999' + chatId,
  texto,
  // messageId real de Telegram: es la clave de idempotencia del debounce de W1 y viene
  // garantizada, así que no hace falta que W1 la derive por hash.
  messageId: 'tg:' + chatId + ':' + String(msg.message_id ?? ''),
  // ── contrato con los nodos de media ────────────────────────────────────────────────
  // Ternario TOTAL: siempre vale una de las tres. Por eso `TG · ruteo media` puede ir sin
  // fallback y no pierde items.
  _tg_ruta: rechazo ? 'no_soportado' : (media ? 'con_media' : 'sin_media'),
  _tg_media: media,
  _media_error: rechazo,
} }];

// Toma el contactId que devolvió W0 y arma el payload GHL definitivo para W1.
const ctx = $('TG → payload GHL').first().json;
const r = $input.first().json || {};
// W0 devuelve el contacto en distintas formas según sea alta o match; se aceptan todas
// en vez de asumir una y romper el día que GHL cambie el shape.
const c = r.contact || r.data?.contact || r.data || r;
const contactId = c.id || c.contactId || c._id;
if (!contactId) {
  throw new Error('W1/TG: upsert_contact no devolvió contactId — ' +
    JSON.stringify(r).slice(0, 200));
}
return [{ json: {
  contactId: String(contactId),
  conversationId: null,
  messageId: ctx.messageId,
  body: ctx.texto,
  // Vacío a propósito. La rama con adjunto la pisa `TG · adjuntar media`, que es el único
  // nodo que llega a conocer la URL pública.
  attachments: [],
  phone: ctx.telefono_sintetico,
  canal: 'Telegram',
  // 0 para texto: en una prueba manual esperar 50s por respuesta es insufrible, y un
  // mensaje escrito no viene en ráfaga. Para media 0 NO sirve — un álbum de Telegram
  // llega como N mensajes independientes y el "gana el último" no alcanza a deduplicar
  // nada. `TG · adjuntar media` lo sube a 15 en esa rama.
  debounce_seg: 0,
  // Se arrastran para el Switch de ruteo y para el aviso de rechazo.
  _tg_ruta: ctx._tg_ruta,
  _media_error: ctx._media_error,
} }];

// ¿Es un comando de reset? Se compara igual que en el handler viejo: texto entero,
// sin espacios, en minúsculas. Así "/reset" resetea y "reset el pedido" no.
const p = $input.first().json;
const COMANDOS = ["/b", "/borrar", "/reset", "/clear", "/nuevo", "/nueva"];
const t = String(p.body || '').trim().toLowerCase();
// El session_id se deriva igual que en `Resolver identidad` de W1 (phone || '2131').
// Si esa fórmula cambia allá, hay que cambiarla acá — es la misma clave de memoria.
const sessionId = String(p.phone || '') + '2131';
const tg = $('TG → payload GHL').first().json;
return [{ json: { ...p, _tg_chat_id_reset: tg._tg_chat_id, _es_reset: COMANDOS.includes(t), _session_id: sessionId } }];

